By the fact that $|U_j|\le m^{k}$, $\|2^kx_i\|_F\le 1$ and using Lemma \ref{lemma:Kahane}
\begin{equation}
    \begin{aligned}
       \left( \mathbb{E} \left\| \sum_{i \in U_j} \epsilon_i x_i \right\|_F^s \right)^{\frac{1}{s}} \lesssim\mathbb{E} \left\| \sum_{i \in U_j} \epsilon_i x_i \right\|_F
       = \frac{1}{2^k}\mathbb{E} \left\| \sum_{i \in U_j} \epsilon_i \left(2^kx_i\right) \right\|_F\leq \frac{1}{2^{j}} m^{k/q} = \frac{1}{2^{j}} m^{k/s} m^{-\tau k}.
    \end{aligned}
\end{equation}
